#!/usr/bin/env node
/**
 * Build the teleproto bundle used by PebbleKit JS.
 *
 * teleproto selects its browser platform implementations through the
 * "#platform/*" conditional imports in its package.json, so this must be built
 * for the browser. The output is CommonJS because bundle_loader.js requires it.
 */
const path = require('path');
const esbuild = require('esbuild');

const outfile = path.join(__dirname, '..', 'src', 'pkjs', 'lib', 'telegram-bundle.js');

esbuild.buildSync({
    entryPoints: [path.join(__dirname, 'telegram-entry.js')],
    outfile: outfile,
    bundle: true,
    platform: 'browser',
    format: 'cjs',
    // Webpack 4 (used by the Pebble SDK) cannot parse newer syntax such as
    // the exponentiation operator, so downlevel to ES2015.
    target: ['es2015'],
    minify: true,
    sourcemap: false,
    legalComments: 'none',
    define: {
        'process.env.NODE_ENV': '"production"'
    },
    banner: {
        js: '// Telegram/teleproto bundle for Squire (PebbleKit JS).\n' +
            '// Generated by scripts/build-telegram-bundle.js; do not edit by hand.'
    },
    logLevel: 'info'
});

console.log('Wrote ' + path.relative(process.cwd(), outfile));
